const DefaultPrivacyPolicyVersion = "1.0"

// DefaultPrivacyPolicyHTML — текст политики обработки ПДн по умолчанию (12 Безопасность и ПДн, раздел 8).
// Переменные: org.*, pdn_retention_years, pdn_consent_purpose.
const DefaultPrivacyPolicyHTML = `<h2>Политика обработки персональных данных</h2>
<p>Оператор: {{org.full_name}}, ИНН {{org.inn}}, адрес: {{org.address}}, e-mail: {{org.email}}.</p>
<h3>1. Цели обработки</h3><p>Заключение и исполнение договоров найма и аренды, расчёты и выдача платёжных документов, исполнение требований законодательства о налогах и о применении контрольно-кассовой техники, работа личного кабинета; при наличии отдельного согласия субъекта — {{pdn_consent_purpose}}.</p>
<h3>2. Состав данных</h3><p>Фамилия, имя, отчество; дата рождения; данные документа, удостоверяющего личность; адрес регистрации; телефон; адрес электронной почты; сведения о совместно проживающих лицах; сведения о платежах, показаниях приборов учёта и заявках.</p>
<h3>3. Правовые основания</h3><p>Заключение и исполнение договора, стороной или выгодоприобретателем по которому является субъект, в том числе сведения о совместно проживающих гражданах (п. 5 ч. 1 ст. 6 Федерального закона № 152-ФЗ, ст. 677 ГК РФ); исполнение обязанностей, возложенных законодательством о налогах и о применении контрольно-кассовой техники (п. 2 ч. 1 ст. 6); законные интересы оператора по защите своих прав в пределах срока исковой давности (п. 7 ч. 1 ст. 6). Для цели «{{pdn_consent_purpose}}» данные обрабатываются только при наличии отдельного согласия субъекта.</p>
<h3>4. Действия с данными</h3><p>Сбор, запись, систематизация, хранение, уточнение, использование, передача (платёжному сервису и оператору фискальных данных — только адрес электронной почты для направления чека), обезличивание, удаление. Обработка ведётся с использованием информационной системы, размещённой на серверах в Российской Федерации.</p>
<h3>5. Сроки</h3><p>В течение срока действия договора и {{pdn_retention_years}} лет после его окончания, после чего данные обезличиваются.</p>
<h3>6. Права субъекта</h3><p>Получать сведения об обработке, требовать уточнения, блокирования или уничтожения данных, отозвать согласие, обратившись к оператору по указанному адресу электронной почты.</p>
<h3>7. Меры защиты</h3><p>Разграничение доступа, шифрование паспортных данных, защищённое соединение HTTPS, журналирование действий, резервное копирование.</p>`

